 return TimeframeTechnicalEvidenceV1("t-"+timeframe,BASE_TIME,symbol,exchange,timeframe,"e-"+timeframe,inds,tuple((x,direction if x in {"TREND","MOMENTUM","PATTERNS"} else "UNAVAILABLE") for x in C),tuple((x,strengths if x in {"TREND","MOMENTUM","PATTERNS"} else 0.) for x in C),blockers=blockers, warnings=warnings,trend_bias=direction if direction in {"BULLISH","BEARISH","NEUTRAL","UNAVAILABLE"} else "UNAVAILABLE",momentum_bias=direction if direction in {"BULLISH","BEARISH","NEUTRAL","UNAVAILABLE"} else "UNAVAILABLE",volatility_state="UNAVAILABLE",volume_state="UNAVAILABLE",level_state="UNAVAILABLE",pattern_state=direction if direction in {"BULLISH","BEARISH"} else "NONE" if direction=="NEUTRAL" else "UNAVAILABLE",trend_strength=strengths,momentum_strength=strengths,pattern_strength=strengths,bullish_evidence_count=1 if direction=="BULLISH" else 0,bearish_evidence_count=1 if direction=="BEARISH" else 0,neutral_evidence_count=1 if direction=="NEUTRAL" else 0,valid_indicator_count=len(inds),unavailable_indicator_count=0)
